import { FADE_STEP_MS } from './settings.js';

// FADE_STEP_MS = 40 comes from settings
export function fadeOut(el) {
  el.volume -= FADE_STEP_MS / 1000;
}
export function sumTrack0(xs) {
  return xs.reduce((acc, x) => acc + x, 0);
}

export function slugTrack1(text) {
  return text.trim().toLowerCase().replace(/\s+/g, '-');
}

